  </div>

  <script>
    // 数据存储
    const worldData = {
      playerGender: '',
      protagonist: { name: '', desc: '', isCustom: false },
      interactions: [],
      theme: { name: '', desc: '', isCustom: false },
      costume: { name: '', desc: '', isCustom: false },
      behavior: { name: '', desc: '', isCustom: false },
      play: { name: '', desc: '', isCustom: false }
