      description += `\n准备好开始你的冒险了吗？点击下面的按钮，踏上这段奇妙旅程！`;

      // 显示描述
      document.querySelector('.result-description').textContent = description;

      // 存储生成的世界设定
      storeWorldSettings();
    }

    // 确保每个类别至少有一个选项
    function ensureSelections() {
      const categories = ['theme', 'role', 'clothing', 'behavior', 'gameplay'];
