        'theme': data.主题,
        'role': data.角色,
        'clothing': data.服装,
        'behavior': data.行为,
        'gameplay': data.玩法
      };

      categories.forEach(category => {
        if (selectedOptions[category].length === 0) {
          const options = mappings[category].filter(option => option !== "全部");
          const randomOption = options[Math.floor(Math.random() * options.length)];
          selectedOptions[category].push(randomOption);
        }
      });
    }

    // 存储世界设定到变量中
    function storeWorldSettings() {
      const worldSettings = {
        gender: selectedGender,
        theme: selectedOptions.theme,
        role: selectedOptions.role,
        clothing: selectedOptions.clothing,
        behavior: selectedOptions.behavior,
        gameplay: selectedOptions.gameplay
      };

      // 使用SillyTavern的变量存储功能
      triggerSlash(`/setvar key=worldSettings ${JSON.stringify(worldSettings)}`);
    }

    // 开始冒险
    function beginAdventure() {
      // 获取世界描述
      const worldDescription = document.querySelector('.result-description').textContent;

      // 发送世界设定到聊天
      let message = "💫 **幻想世界已创建** 💫\n\n";
      message += worldDescription;

      triggerSlash(`/send ${message}`);

      // 等待一秒后触发AI响应
      setTimeout(() => {
        triggerSlash('/trigger');
      }, 1000);
    }
